## Author details for the non-anonymised manuscript (title page, acknowledgements, declarations).
## Copy this file to private/author_details.R and fill it in. The private/ folder is excluded from Git (.gitignore),
## so your names never appear in the repository, and a knit without it shows placeholders only.
AUTHOR_DETAILS <- list(
  authors          = "[Author 1 full name]^1^ ([email]; ORCID [0000-0000-0000-0000]), [Author 2 full name]^2^ ([email]; ORCID [0000-0000-0000-0000])",
  affiliations     = c("^1^ [Department], [Faculty], [University], [City], Nigeria",
                       "^2^ [Department], [Faculty], [University], [City], Nigeria"),
  corresponding    = "[Full name], [postal address], [phone], [email], ORCID [0000-0000-0000-0000]",
  acknowledgements = "[The authors thank the participants and the community leaders of Mayo-Belwa, and ...]",
  contributions    = "[Initials] conceived the study and designed the protocol; [initials] collected the photographs and digitized the landmarks; [initials] analyzed the data; [initials] wrote the first draft; all authors revised the manuscript and approved the final version.",
  ethics           = "The study protocol was approved by the Health Research Ethics Committee of the Adamawa State Ministry of Health (approval number [number]) and the Human Research Ethics Committee of [University] (approval number [number])",
  data             = "openly available in [repository name] at [https://doi.org/...]",
  funding          = "[State the source and manner of funding and the role of the funder, or: This research received no specific grant from any funding agency in the public, commercial or not-for-profit sectors.]"
